package com.cet.finder.ui;

import com.cet.finder.dao.CutoffDAO;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.util.List;

/** Admin CRUD screen. Set CET_ADMIN_KEY environment variable before launching. */
public class AdminPanel extends JPanel {
 private final CutoffDAO dao=new CutoffDAO(); private final JTextField key=new JPasswordField(16); private final JButton unlock=new JButton("Unlock admin tools");
 private final JTextField filter=new JTextField(18); private final DefaultTableModel model=new DefaultTableModel(new String[]{"ID","Choice Code","Year","Round","Exam","Allotment","Seat","Category","Merit Rank","Merit Score","Percentile"},0){public boolean isCellEditable(int r,int c){return false;}}; private final JTable table=new JTable(model); private boolean authorized=false;
 public AdminPanel(){setLayout(new BorderLayout(10,10));setBorder(BorderFactory.createEmptyBorder(16,16,16,16));JPanel top=new JPanel(new FlowLayout(FlowLayout.LEFT));top.add(new JLabel("Admin key:"));top.add(key);top.add(unlock);top.add(new JLabel("Filter:"));top.add(filter);JButton refresh=new JButton("Refresh");top.add(refresh);add(top,BorderLayout.NORTH);add(new JScrollPane(table),BorderLayout.CENTER);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT));JButton add=new JButton("Add cutoff"),edit=new JButton("Edit selected"),del=new JButton("Delete selected");actions.add(add);actions.add(edit);actions.add(del);add(actions,BorderLayout.SOUTH);setTools(false,add,edit,del,refresh);unlock.addActionListener(e->{String expected=System.getenv().getOrDefault("CET_ADMIN_KEY",System.getProperty("cet.admin.key",""));if(expected.isBlank()){msg("Set the CET_ADMIN_KEY environment variable before starting the app.",JOptionPane.WARNING_MESSAGE);return;}authorized=expected.equals(new String(((JPasswordField)key).getPassword()));setTools(authorized,add,edit,del,refresh);msg(authorized?"Admin tools unlocked for this session.":"Incorrect admin key.",authorized?JOptionPane.INFORMATION_MESSAGE:JOptionPane.ERROR_MESSAGE);if(authorized)load();});refresh.addActionListener(e->{if(authorized)load();});filter.addActionListener(e->{if(authorized)load();});add.addActionListener(e->{if(authorized)edit(null);});edit.addActionListener(e->{if(authorized)edit(selected());});del.addActionListener(e->{if(!authorized)return;String[] row=selected();if(row==null)return;if(JOptionPane.showConfirmDialog(this,"Delete cutoff ID "+row[0]+"? The database audit trigger should record this.","Confirm",JOptionPane.YES_NO_OPTION)==JOptionPane.YES_OPTION)try{dao.delete(Long.parseLong(row[0]));load();}catch(Exception ex){error(ex);}});}
 private void setTools(boolean on,JButton add,JButton edit,JButton del,JButton refresh){add.setEnabled(on);edit.setEnabled(on);del.setEnabled(on);refresh.setEnabled(on);filter.setEnabled(on);}
 private String[] selected(){int r=table.getSelectedRow();if(r<0){msg("Select a cutoff row first.",JOptionPane.WARNING_MESSAGE);return null;}String[] a=new String[11];for(int i=0;i<11;i++)a[i]=String.valueOf(model.getValueAt(table.convertRowIndexToModel(r),i));return a;}
 private void load(){try{model.setRowCount(0);List<String[]> rows=dao.search(filter.getText());for(String[] r:rows)model.addRow(r);}catch(Exception e){error(e);}}
 private void edit(String[] old){JTextField[] f=new JTextField[10];String[] labels={"Choice code","Year","CAP round","Merit exam","Allotment type","Seat type","Category","Merit rank (blank if none)","Merit score (blank if none)","Percentile (blank if none)"};JPanel p=new JPanel(new GridLayout(10,2,5,5));for(int i=0;i<10;i++){p.add(new JLabel(labels[i]));f[i]=new JTextField(old==null?"":old[i+1]);p.add(f[i]);}if(JOptionPane.showConfirmDialog(this,p,old==null?"Add cutoff":"Edit cutoff",JOptionPane.OK_CANCEL_OPTION)!=JOptionPane.OK_OPTION)return;try{String choice=f[0].getText().trim();int year=Integer.parseInt(f[1].getText().trim()),round=Integer.parseInt(f[2].getText().trim());String exam=f[3].getText().trim(),allot=f[4].getText().trim(),seat=f[5].getText().trim(),cat=f[6].getText().trim();Integer rank=f[7].getText().isBlank()?null:Integer.valueOf(f[7].getText().trim());Double score=f[8].getText().isBlank()?null:Double.valueOf(f[8].getText().trim()),pct=f[9].getText().isBlank()?null:Double.valueOf(f[9].getText().trim());if(old==null)dao.insert(choice,year,round,exam,allot,seat,cat,rank,score,pct);else dao.update(Long.parseLong(old[0]),choice,year,round,exam,allot,seat,cat,rank,score,pct);load();}catch(Exception e){error(e);}}
 private void msg(String s,int type){JOptionPane.showMessageDialog(this,s,"Admin",type);}private void error(Exception e){msg(e.getMessage(),JOptionPane.ERROR_MESSAGE);}
}
